const results = [];
const allInputs = $input.all();
const testCases = $('載入測試用例1').all();

for (let i = 0; i < allInputs.length; i++) {
  const itemJson = allInputs[i].json;
  const expected = testCases[i].json.expected;
  const inputStr = testCases[i].json.input;
  const testId = testCases[i].json.id;

  let rawText = "";
  try {
    rawText = itemJson.candidates[0].content.parts[0].text.trim();
  } catch (e) {
    rawText = "";
  }

  let actual = {};
  let isPass = true;
  let reason = "匹配成功";

  try {
    actual = JSON.parse(rawText);

    if (actual.canAnswer !== expected.canAnswer) {
      isPass = false;
      reason = `canAnswer 不符 (實際: ${actual.canAnswer}, 預期: ${expected.canAnswer})`;
    } else if (actual.matchType !== expected.matchType) {
      isPass = false;
      reason = `matchType 不符 (實際: ${actual.matchType}, 預期: ${expected.matchType})`;
    } else if (expected.matchType === "exact") {
      if (String(actual.matchedId) !== String(expected.matchedId)) {
        isPass = false;
        reason = `matchedId 不符 (實際: '${actual.matchedId}', 預期: '${expected.matchedId}')`;
      }
    } else if (expected.matchType === "ambiguous") {
      if (actual.ambiguousGroup !== expected.ambiguousGroup) {
        isPass = false;
        reason = `ambiguousGroup 不符 (實際: '${actual.ambiguousGroup}', 預期: '${expected.ambiguousGroup}')`;
      } else {
        const actOpts = (actual.options || []).map(o => `${o.label}:${o.id}`).sort().join(",");
        const expOpts = (expected.options || []).map(o => `${o.label}:${o.id}`).sort().join(",");
        if (actOpts !== expOpts) {
          isPass = false;
          reason = `options 選項不符 (實際: [${actOpts}], 預期: [${expOpts}])`;
        }
      }
    }
  } catch (e) {
    isPass = false;
    reason = "非合法 JSON 格式: " + rawText;
  }

  results.push({
    json: {
      id: testId,
      input: inputStr,
      isPass,
      reason,
      actual,
      expected
    }
  });
}

return results;

const items = $input.all();
const total = items.length;
const passed = items.filter(i => i.json.isPass).length;
const failures = items.filter(i => !i.json.isPass).map(i => ({
  id: i.json.id,
  input: i.json.input,
  reason: i.json.reason,
  actual: i.json.actual,
  expected: i.json.expected
}));

return {
  json: {
    summary: `測試完成！通過率: ${passed}/${total} (${((passed / total) * 100).toFixed(1)}%)`,
    passedCount: passed,
    totalCount: total,
    failCount: total - passed,
    failures
  }
};

